CREATE TABLE "PricingProfile" ("id" TEXT NOT NULL DEFAULT 'default', "internalHourlyCostCents" INTEGER NOT NULL DEFAULT 6000, "targetMarginBps" INTEGER NOT NULL DEFAULT 4000, "taxBps" INTEGER NOT NULL DEFAULT 600, "riskReserveBps" INTEGER NOT NULL DEFAULT 1500, "weeklyCapacityHours" INTEGER NOT NULL DEFAULT 30, "minimumProjectCents" INTEGER NOT NULL DEFAULT 300000, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PricingProfile_pkey" PRIMARY KEY ("id"));
